head.script:
// https://inswave01.atlassian.net/browse/WAEA-1209
// https://inswave01.atlassian.net/browse/WAEA-1210
// 테스트 설명, 유효성 값 설정
//  ★ _12 : dummy_xlsform (Excel 파일 서식 옵션) 계열 중 행 높이 / 자동 줄바꿈 / 숨김 옵션 - rowHeight / bodyWordwrap / subtotalWordwrap / footerWordwrap / excludeColumnsWordWrap / foldColumns / excludeFoldColumnsWordWrap
//     description 은 분리 샘플 공통(_1 과 동일).
scwin.tData = {
    "description" : "[gridView > M > advancedExcelDownload]<br/>GridView 컴포넌트의 데이터를 Excel 파일로 다운로드합니다.",
    "validation" : [
        "rowHeight(선택) 파라미터로 Excel 파일의 데이터 행 높이를 픽셀(pixel) 단위로 설정합니다.",
        "rowHeight(선택) 파라미터를 생략하면 기본값 -1 이 적용됩니다.",
        "bodyWordwrap(선택) 파라미터로 GridView 의 Body 영역 데이터에 Excel 의 '자동 줄바꿈' 서식을 적용할지 true/false 로 설정합니다.",
        "bodyWordwrap(선택) 파라미터를 생략하면 기본값 false 가 적용됩니다.",
        "subtotalWordwrap(선택) 파라미터로 GridView 의 SubTotal 영역 데이터에 Excel 의 '자동 줄바꿈' 서식을 적용할지 true/false 로 설정합니다.",
        "subtotalWordwrap(선택) 파라미터를 생략하면 기본값 false 가 적용됩니다.",
        "footerWordwrap(선택) 파라미터로 GridView 의 Footer 영역 데이터에 Excel 의 '자동 줄바꿈' 서식을 적용할지 true/false 로 설정합니다.",
        "footerWordwrap(선택) 파라미터를 생략하면 기본값 false 가 적용됩니다.",
        "excludeColumnsWordWrap(선택) 파라미터로 bodyWordwrap 파라미터값이 true 일때 Excel 의 '자동 줄바꿈' 서식 적용에서 제외할 Column 의 인덱스를 콤마(,)로 구분하여 설정합니다.",
        "excludeColumnsWordWrap(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "foldColumns(선택) 파라미터로 Excel 파일에서 '숨김' 처리하려는 Column 의 인덱스를 콤마(,)로 구분하여 설정합니다.",
        "foldColumns(선택) 파라미터에 설정한 Column 의 위치가 변경되어도 Column 의 인덱스는 변경되지 않습니다.",
        "foldColumns(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "excludeFoldColumnsWordWrap(선택) 파라미터로 foldColumns 파라미터에 설정된 Column 에 Excel 의 '자동 줄바꿈' 서식을 제거할지 설정합니다.",
        "excludeFoldColumnsWordWrap(선택) 파라미터를 'true' 로 설정 시 bodyWordwrap 파라미터값에 관계없이 해당 Column 에 Excel 의 '자동 줄바꿈' 서식을 적용하지 않습니다.",
        "excludeFoldColumnsWordWrap(선택) 파라미터를 'false' 로 설정 시 bodyWordwrap 파라미터값에 따라 해당 Column 에 Excel 의 '자동 줄바꿈' 서식을 적용합니다.",
        "excludeFoldColumnsWordWrap(선택) 파라미터를 생략하면 기본값 'false' 가 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : Header / Body / SubTotal / Footer 를 모두 갖춘 GridView 를 동적 생성한다.
//  · advancedExcelDownload 는 DataList 바인딩이 전제 조건이므로 dataList 속성을 반드시 설정한다.
//  · Body Column 인덱스 0:구분 1:품목설명 2:보관위치 3:비고 4:수량
//     - 인덱스 1 / 2 / 3 은 Cell 폭보다 긴 텍스트 -> 자동 줄바꿈(wrapText) 서식 적용 여부 확인용
//     - 각 값 앞에 인덱스를 표기하여 excludeColumnsWordWrap / foldColumns 로 지정한 Column 을 파일에서 구분할 수 있게 한다.
//  · SubTotal(구분 기준) : 인덱스 1 에 긴 텍스트 -> subtotalWordwrap 확인용
//  · Footer : 인덱스 1 에 긴 텍스트 -> footerWordwrap 확인용
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- Body Column 인덱스 0 구분 / 1 품목설명 / 2 보관위치 / 3 비고 / 4 수량, Body Row 는 6행\n- 인덱스 1 / 2 / 3 은 Cell 폭보다 긴 텍스트이고 값 앞에 (인덱스n ...) 표기가 있어 파일에서 어느 Column 인지 바로 구분됨\n- SubTotal(구분 기준 소계 2행) 과 Footer(합계 1행) 의 인덱스 1 에도 긴 텍스트가 있어 영역별 자동 줄바꿈 적용 차이를 확인할 수 있음\n- useSubTotal=true 는 SubTotal 행을 파일에 포함시키기 위한 고정 전달값(본 계열 검증 대상 아님)\n- 파일명 download_xlsform, 확장자 xlsx 고정 전달(본 계열 검증 대상 아님)\n- columnMove / columnOrder 는 본 계열의 검증 대상이 아니며, foldColumns 하위 조건(Column 의 위치가 변경되어도 Column 의 인덱스는 변경되지 않음) 을 확인하기 위한 보조 옵션이다. columnMove=true 와 columnOrder 를 함께 주면 파일의 Column 순서가 지정한 인덱스 순서로 바뀐다 (columnOrder 2,1,0,3,4 를 주면 보관위치 - 품목설명 - 구분 - 비고 - 수량 순서)\n[절차]\n1. par 옵션(rowHeight / bodyWordwrap / subtotalWordwrap / footerWordwrap / excludeColumnsWordWrap / foldColumns / excludeFoldColumnsWordWrap) 값을 선택한다\n2. advancedExcelDownload 버튼을 클릭해 Excel 파일을 내려받는다\n3. foldColumns 의 인덱스 불변 조건을 확인하려면 보조 옵션 columnMove=true 와 columnOrder 를 함께 선택한 뒤 다운로드한다\n[확인]\n- 이 계열은 Cell 값이 아니라 Excel 의 서식과 구조를 바꾸므로 값만 봐서는 차이가 보이지 않는다. 내려받은 파일을 Excel 로 열어 행 높이 / 셀 서식(맞춤 - 텍스트 줄바꿈) / 열 숨김 상태로 확인한다\n- rowHeight : 설정한 픽셀값이 Excel 의 행 높이로 적용되는지. Excel 은 행 높이를 포인트 단위로 저장하므로 픽셀값의 0.75 배가 기록된다 (20 -> 15 / 40 -> 30 / 80 -> 60). 미설정이면 기본값 -1 이 적용되어 행 높이가 지정되지 않는지. 행 높이는 Header / 소계 / 합계 행을 포함한 전체 행에 함께 적용된다\n- bodyWordwrap : true 면 Body 영역 Cell 에 텍스트 줄바꿈 서식이 켜져 긴 값이 여러 줄로 표시되는지, false 또는 미설정이면 꺼져 있는지\n- subtotalWordwrap : 소계 행의 긴 텍스트 Cell 에 줄바꿈 서식이 적용되는지 (Body 영역과 별개로 동작). 참고로 현재 엔진에서는 소계 행이 미설정 상태에서도 줄바꿈 서식이 적용된 상태로 생성된다\n- footerWordwrap : 합계 행의 긴 텍스트 Cell 에 줄바꿈 서식이 적용되는지 (Body 영역과 별개로 동작). 참고로 현재 엔진에서는 합계 행이 미설정 상태에서도 줄바꿈 서식이 적용된 상태로 생성된다\n- excludeColumnsWordWrap : bodyWordwrap=true 인 상태에서 지정한 인덱스의 Column 만 줄바꿈 서식이 빠지는지\n- foldColumns : 지정한 인덱스의 Column 이 Excel 에서 숨김(열 숨기기) 상태로 열리는지, 숨긴 열을 표시하면 데이터는 그대로 있는지. 또한 보조 옵션 columnMove=true 와 columnOrder 로 Column 순서를 바꾼 뒤에도 지정한 원래 인덱스의 Column 이 (자리는 옮겨졌더라도) 그대로 숨겨지는지 확인한다. 어느 Column 이 숨겨졌는지는 셀 값 앞의 (인덱스n ...) 표기로 대조한다\n- excludeFoldColumnsWordWrap : true 면 foldColumns 로 숨긴 Column 은 bodyWordwrap 값과 무관하게 줄바꿈 서식이 빠지는지, false 또는 미설정이면 bodyWordwrap 값을 그대로 따르는지. 숨겨진 Column 이라 셀 서식을 바로 볼 수 없으므로 Excel 에서 해당 열의 [열 숨기기 취소] 로 숨김을 해제한 뒤 셀 서식(맞춤 - 텍스트 줄바꿈)을 확인한다\n- 결과창의 서버 전달값으로 실제 서버에 전송된 7개 옵션 원문을 함께 확인. bodyWordwrap / subtotalWordwrap / footerWordwrap 는 Boolean 파라미터라 false 를 선택하면 엔진이 요청에 담지 않아 (미전달) 로 표시되며 이는 기본값 false 와 동일한 동작이다"', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 DataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="category" name="category" dataType="text"></w2:column>';
    strDlt += '<w2:column id="itemDesc" name="itemDesc" dataType="text"></w2:column>';
    strDlt += '<w2:column id="location" name="location" dataType="text"></w2:column>';
    strDlt += '<w2:column id="note" name="note" dataType="text"></w2:column>';
    strDlt += '<w2:column id="qty" name="qty" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "category" : "사무기기",   "itemDesc" : "(인덱스1 품목설명) 27인치 광시야각 모니터, 베사 마운트 지원 및 3년 무상 보증 포함", "location" : "(인덱스2 보관위치) 본관 3층 전산실 A구역 세번째 캐비닛 상단 칸", "note" : "(인덱스3 비고) 2026년 상반기 정기 자산실사에서 상태 양호로 확인됨", "qty" : 12 },
        { "category" : "사무기기",   "itemDesc" : "(인덱스1 품목설명) 15인치 업무용 노트북, 도킹 스테이션과 전용 어댑터 동봉", "location" : "(인덱스2 보관위치) 본관 3층 전산실 B구역 두번째 캐비닛 중간 칸", "note" : "(인덱스3 비고) 신규 입사자 배정 대기 물량으로 개봉하지 않은 상태", "qty" : 8 },
        { "category" : "사무기기",   "itemDesc" : "(인덱스1 품목설명) 듀얼 모니터암 세트, 클램프 방식과 그로밋 방식 부속 포함", "location" : "(인덱스2 보관위치) 별관 1층 자재창고 선반 두번째 줄 왼쪽 구획", "note" : "(인덱스3 비고) 부속품 일부 누락 가능성이 있어 출고 전 수량 확인 필요", "qty" : 5 },
        { "category" : "전산소모품", "itemDesc" : "(인덱스1 품목설명) 무선 광마우스, 수신기 일체형이며 건전지는 별도 구매 필요", "location" : "(인덱스2 보관위치) 별관 1층 자재창고 선반 첫번째 줄 오른쪽 구획", "note" : "(인덱스3 비고) 소모품 특성상 반기 단위로 재고 회전율을 점검하고 있음", "qty" : 40 },
        { "category" : "전산소모품", "itemDesc" : "(인덱스1 품목설명) 기계식 키보드 텐키리스 모델, 갈축 스위치와 손목 받침 포함", "location" : "(인덱스2 보관위치) 별관 1층 자재창고 선반 첫번째 줄 가운데 구획", "note" : "(인덱스3 비고) 개발팀 요청으로 별도 확보한 물량이라 타 부서 배정 불가", "qty" : 15 },
        { "category" : "전산소모품", "itemDesc" : "(인덱스1 품목설명) 노이즈캔슬링 헤드셋, 유선과 무선 겸용이며 전용 케이스 포함", "location" : "(인덱스2 보관위치) 창고동 2층 임시 적재구역 파렛트 세번째 열", "note" : "(인덱스3 비고) 화상회의 확대에 따라 추가 발주가 예정되어 있는 품목", "qty" : 22 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // target 생성 (DataList 바인딩)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:820px;height:420px;">';
    strTarget += '<w2:caption style="" id="caption1" value="advancedExcelDownload (행 높이 / 자동 줄바꿈 / 숨김 옵션) 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol1" value="구분"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="hcol2" value="품목설명"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="hcol3" value="보관위치"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="hcol4" value="비고"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol5" value="수량"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="category" dataList="category"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="itemDesc" dataList="itemDesc"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="location" dataList="location"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="note" dataList="note"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" id="qty" dataList="qty"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    // SubTotal : 인덱스 1 에 긴 텍스트 (subtotalWordwrap 확인용)
    strTarget += '<w2:subTotal style="" id="subTotal1" targetColumnID="category">';
    strTarget += '<w2:row style="" id="srow1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="scol1" value="소계"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="scol2" value="(소계 행) 구분 단위로 집계한 소계 행이며 자동 줄바꿈 서식 확인용 긴 문구입니다"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="scol3" value=""></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="scol4" value=""></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="expression" dataType="number" id="scol5" expression="sum(\'qty\')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:subTotal>';
    // Footer : 인덱스 1 에 긴 텍스트 (footerWordwrap 확인용)
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="frow1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="fcol1" value="합계"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="fcol2" value="(합계 행) 전체 자산을 합산한 합계 행이며 자동 줄바꿈 서식 확인용 긴 문구입니다"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="fcol3" value=""></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="fcol4" value=""></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="expression" dataType="number" id="fcol5" expression="sum(\'qty\')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// par 옵션값으로 advancedExcelDownload options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · rowHeight 는 Number 타입, bodyWordwrap / subtotalWordwrap / footerWordwrap 는 Boolean 타입 파라미터이므로 해당 타입으로 변환하여 전달한다.
//  · fileName / extension 은 다운로드 파일 확인 편의를 위한 고정값, useSubTotal 은 SubTotal 행을 파일에 포함시키기 위한 고정값이며 본 계열의 검증 대상이 아니다.
scwin.buildOptions = function () {
    let options = { "fileName" : "download_xlsform", "extension" : "xlsx", "useSubTotal" : "true" };
    let arrDesc = [];

    let fnSet = function (sKey, vValue) {
        options[sKey] = vValue;
        arrDesc.push(sKey + "=" + vValue);
    };

    let v;
    v = par_rowHeight.getValue();                  if (v !== "") fnSet("rowHeight", parseInt(v, 10));
    v = par_bodyWordwrap.getValue();               if (v !== "") fnSet("bodyWordwrap", (v === "true"));
    v = par_subtotalWordwrap.getValue();           if (v !== "") fnSet("subtotalWordwrap", (v === "true"));
    v = par_footerWordwrap.getValue();             if (v !== "") fnSet("footerWordwrap", (v === "true"));
    v = par_excludeColumnsWordWrap.getValue();     if (v !== "") fnSet("excludeColumnsWordWrap", v);
    v = par_foldColumns.getValue();                if (v !== "") fnSet("foldColumns", v);
    v = par_excludeFoldColumnsWordWrap.getValue(); if (v !== "") fnSet("excludeFoldColumnsWordWrap", v);
    // columnMove / columnOrder 는 본 계열(서식 옵션)의 검증 대상이 아니라
    //  foldColumns 하위 조건(Column 의 위치가 변경되어도 Column 의 인덱스는 변경되지 않음) 확인을 위한 보조 옵션이다.
    v = par_columnMove.getValue();                 if (v !== "") fnSet("columnMove", v);
    v = par_columnOrder.getValue();                if (v !== "") fnSet("columnOrder", v);

    return { "options" : options, "desc" : ((arrDesc.length === 0) ? "{} (rowHeight / bodyWordwrap / subtotalWordwrap / footerWordwrap / excludeColumnsWordWrap / foldColumns / excludeFoldColumnsWordWrap 전체 생략)" : arrDesc.join(" / ")) };
}



// 다운로드 요청 캡처 : 다운로드는 숨겨진 iframe 으로 form 전송되며 form 은 전송 직후 제거되므로,
//  메소드 호출 구간에서만 form submit 을 감싸 서버로 실제 전달되는 값을 읽고 곧바로 원복한다. (실제 요청은 그대로 통과)
scwin.hookRequest = function () {
    scwin.gVar = { "body" : "" };

    let fnSubmit = HTMLFormElement.prototype.submit;
    HTMLFormElement.prototype.submit = function () {
        if (scwin.gVar.body === "") {
            let objInput = this.querySelector("input[name=xmlValue]");
            scwin.gVar.body = (objInput === null) ? "" : objInput.value;
        }
        return fnSubmit.apply(this, arguments);
    };

    scwin.gVar.unhook = function () {
        HTMLFormElement.prototype.submit = fnSubmit;
    };
}



// 캡처한 요청 본문에서 서버로 전달된 옵션값을 읽는다. (전달되지 않은 옵션은 미전달로 표시)
scwin.getSentValue = function (sKey) {
    let sBody = scwin.gVar.body || "";
    let nKey = sBody.indexOf("hashkey='" + sKey + "'");
    if (nKey < 0) return "(미전달)";

    let sRest = sBody.substring(nKey);
    let nVal = sRest.indexOf("value='");
    if (nVal < 0) return "(미전달)";

    sRest = sRest.substring(nVal + 7);
    return sRest.substring(0, sRest.indexOf("'"));
}



// advancedExcelDownload 실행
scwin.btn_advancedExcelDownload_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let objBuild = scwin.buildOptions();

    scwin.hookRequest();
    try {
        target1.advancedExcelDownload(objBuild.options);
    } finally {
        scwin.gVar.unhook();
    }

    bottom.setReturnValue("전달 옵션 : " + objBuild.desc);
    bottom.setReturnValue("서버 전달값 : rowHeight=" + scwin.getSentValue("rowHeight") + " / bodyWordwrap=" + scwin.getSentValue("bodyWordwrap") + " / subtotalWordwrap=" + scwin.getSentValue("subtotalWordwrap") + " / footerWordwrap=" + scwin.getSentValue("footerWordwrap"));
    bottom.setReturnValue("서버 전달값 : excludeColumnsWordWrap=" + scwin.getSentValue("excludeColumnsWordWrap") + " / foldColumns=" + scwin.getSentValue("foldColumns") + " / excludeFoldColumnsWordWrap=" + scwin.getSentValue("excludeFoldColumnsWordWrap"));
}
